<?php
require "db.php";$pageTitle="Lecturer";$id=0;$staff_no="";$fName="";$lName="";$email="";$phone="";$dept_id="";
if(isset($_POST['save'])){$id=(int)$_POST['lecturer_id'];$staff=mysqli_real_escape_string($conn,$_POST['staff_no']);$fn=mysqli_real_escape_string($conn,$_POST['fName']);$ln=mysqli_real_escape_string($conn,$_POST['lName']);$em=mysqli_real_escape_string($conn,$_POST['email']);$ph=mysqli_real_escape_string($conn,$_POST['phone']);$d=(int)$_POST['dept_id'];$sql=$id?"UPDATE lecturer SET staff_no='$staff',fName='$fn',lName='$ln',email='$em',phone='$ph',dept_id=$d WHERE lecturer_id=$id":"INSERT INTO lecturer(staff_no,fName,lName,email,phone,dept_id) VALUES('$staff','$fn','$ln','$em','$ph',$d)";if(mysqli_query($conn,$sql)){header("Location: lecturer.php?message=Lecturer saved successfully");exit;}$error=mysqli_error($conn);}
if(isset($_POST['delete'])){$id=(int)$_POST['delete_id'];if(mysqli_query($conn,"DELETE FROM lecturer WHERE lecturer_id=$id")){header("Location: lecturer.php?message=Lecturer deleted successfully");exit;}$error=mysqli_error($conn);}
if(isset($_GET['edit'])){$id=(int)$_GET['edit'];$r=mysqli_fetch_assoc(mysqli_query($conn,"SELECT * FROM lecturer WHERE lecturer_id=$id"));if($r){$staff_no=$r['staff_no'];$fName=$r['fName'];$lName=$r['lName'];$email=$r['email'];$phone=$r['phone'];$dept_id=$r['dept_id'];}}
require "header.php";if(isset($error))echo '<div class="message error">'.htmlspecialchars($error).'</div>';?>
<h1>Lecturer Form</h1><div class="card"><form action="lecturer.php" method="POST"><input type="hidden" name="lecturer_id" value="<?php echo $id;?>"><div class="form-grid"><div class="field"><label>Staff Number</label><input name="staff_no" value="<?php echo htmlspecialchars($staff_no);?>" required></div><div class="field"><label>First Name</label><input name="fName" value="<?php echo htmlspecialchars($fName);?>" required></div><div class="field"><label>Last Name</label><input name="lName" value="<?php echo htmlspecialchars($lName);?>" required></div><div class="field"><label>Email</label><input type="email" name="email" value="<?php echo htmlspecialchars($email);?>" required></div><div class="field"><label>Phone</label><input name="phone" value="<?php echo htmlspecialchars($phone);?>" required></div><div class="field"><label>Department</label><select name="dept_id" required><option value="">Select Department</option><?php $d=mysqli_query($conn,"SELECT * FROM department ORDER BY dept_code");while($x=mysqli_fetch_assoc($d))echo '<option value="'.$x['dept_id'].'" '.($dept_id==$x['dept_id']?'selected':'').'>'.htmlspecialchars($x['dept_code'].' - '.$x['dept_name']).'</option>';?></select></div></div><div class="actions"><button class="btn" name="save"> <?php echo $id?'Update Lecturer':'Save Lecturer';?></button><a class="btn secondary" href="lecturer.php">Clear</a></div></form></div>
<div class="card"><h2>Lecturer Records</h2><div class="table-wrap"><table><tr><th>lecturer_id</th><th>Staff No.</th><th>First</th><th>Last</th><th>Email</th><th>Phone</th><th>Department</th><th>Actions</th></tr><?php $q=mysqli_query($conn,"SELECT l.*,d.dept_name FROM lecturer l JOIN department d ON d.dept_id=l.dept_id ORDER BY l.lecturer_id DESC");while($r=mysqli_fetch_assoc($q)){echo '<tr><td>'.$r['lecturer_id'].'</td><td>'.htmlspecialchars($r['staff_no']).'</td><td>'.htmlspecialchars($r['fName']).'</td><td>'.htmlspecialchars($r['lName']).'</td><td>'.htmlspecialchars($r['email']).'</td><td>'.htmlspecialchars($r['phone']).'</td><td>'.htmlspecialchars($r['dept_name']).'</td><td><a class="btn" href="lecturer.php?edit='.$r['lecturer_id'].'">Edit</a> <form action="lecturer.php" method="POST" style="display:inline"><input type="hidden" name="delete_id" value="'.$r['lecturer_id'].'"><button class="btn danger" name="delete" onclick="return confirm(\'Delete?\')">Delete</button></form></td></tr>';}?></table></div></div><?php require "footer.php";?>
